INSERT INTO glosses(id,locale,text,usage_label,source_id,status) VALUES
  ('gloss-word-bangmang','id','membantu; memberi bantuan','Sering dipakai dalam 请帮忙 untuk meminta bantuan dengan sopan.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-xuyao','id','membutuhkan; perlu','Diikuti kata benda atau kata kerja untuk menyatakan kebutuhan.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-chidao','id','terlambat','Tidak tiba pada waktu yang telah disepakati atau ditentukan.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-zaodao','id','tiba lebih awal','Tiba sebelum waktu yang telah disepakati atau diperkirakan.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-zhongyu','id','akhirnya','Menekankan bahwa sesuatu terjadi setelah menunggu, mencoba, atau melalui proses.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-jixu','id','melanjutkan','Melakukan lagi atau tetap melakukan sesuatu yang belum selesai.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-gan-kuai','id','cepat-cepat; segera','Mendorong agar suatu tindakan dilakukan tanpa menunda.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-jihua','id','rencana; merencanakan','Dapat menjadi kata benda atau kata kerja untuk menyusun tindakan ke depan.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-canjia','id','ikut serta; menghadiri','Diikuti nama kegiatan, acara, kelas, atau pertemuan.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-huodong','id','kegiatan; acara','Acara atau kegiatan yang dilakukan sendiri maupun bersama orang lain.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-jianmian','id','bertemu; bertatap muka','Bertemu seseorang secara langsung; pola umum: 跟 + orang + 见面.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-haimei','id','belum','Menyatakan tindakan belum terjadi sampai saat ini; biasanya diikuti kata kerja.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-renwei','id','berpendapat; menganggap','Memperkenalkan pendapat yang dapat diikuti klausa dengan 是 atau 很.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-bijiao','id','cukup; relatif; membandingkan','Sebelum kata sifat dapat berarti ''cukup/relatif''; sebagai kata kerja berarti membandingkan.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-renzhen','id','serius; sungguh-sungguh','Menggambarkan cara melakukan sesuatu dengan perhatian dan kesungguhan.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-tebie','id','sangat; khusus; istimewa','Sebelum kata sifat berarti sangat; sebagai kata sifat dapat berarti khusus atau istimewa.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-kaishi','id','mulai; permulaan','Menunjukkan awal suatu tindakan; dapat langsung diikuti kata kerja.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-wancheng','id','menyelesaikan','Menyatakan suatu tugas atau pekerjaan sudah dikerjakan sampai tuntas.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-jieguo','id','hasil; akibat','Hasil yang muncul setelah proses atau tindakan; dapat juga menjadi penghubung untuk ''ternyata''.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-jihui','id','kesempatan; peluang','Waktu atau keadaan yang memungkinkan seseorang melakukan sesuatu.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-jingyan','id','pengalaman','Pengetahuan atau keterampilan yang diperoleh dari melakukan sesuatu.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-wenhua','id','budaya','Kebiasaan, gagasan, seni, dan cara hidup yang berkembang dalam masyarakat.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-xiguan','id','kebiasaan; terbiasa','Sebagai kata benda berarti rutinitas; pola 习惯 + kata kerja berarti terbiasa melakukan sesuatu.','source-course-expansion-2026-09-advanced','approved'),
  ('gloss-word-bianhua','id','perubahan; berubah','Dapat menjadi kata benda untuk perubahan atau kata kerja untuk menyatakan sesuatu berubah.','source-course-expansion-2026-09-advanced','approved');

