INSERT INTO examples(id,vocabulary_id,character_id,simplified_text,pinyin_json,numbered_pinyin,locale,translation,source_id,status) VALUES
  ('example-word-bangmang','word-bangmang',NULL,'你可以帮我一个忙吗？','["nǐ","kě","yǐ","bāng","wǒ","yí","ge","máng","ma"]','ni3 ke3 yi3 bang1 wo3 yi2 ge0 mang2 ma0','id','Bisakah kamu membantu saya?','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-xuyao','word-xuyao',NULL,'我需要一点时间准备。','["wǒ","xū","yào","yì","diǎn","shí","jiān","zhǔn","bèi"]','wo3 xu1 yao4 yi4 dian3 shi2 jian1 zhun3 bei4','id','Saya perlu sedikit waktu untuk bersiap.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-chidao','word-chidao',NULL,'下雨了，我们可能会迟到。','["xià","yǔ","le","wǒ","men","kě","néng","huì","chí","dào"]','xia4 yu3 le0 wo3 men0 ke3 neng2 hui4 chi2 dao4','id','Hujan turun, kita mungkin akan terlambat.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-zaodao','word-zaodao',NULL,'我们早到十分钟，在门口等吧。','["wǒ","men","zǎo","dào","shí","fēn","zhōng","zài","mén","kǒu","děng","ba"]','wo3 men0 zao3 dao4 shi2 fen1 zhong1 zai4 men2 kou3 deng3 ba0','id','Kita tiba sepuluh menit lebih awal; tunggu di pintu saja.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-zhongyu','word-zhongyu',NULL,'我找了很久，终于找到车站了。','["wǒ","zhǎo","le","hěn","jiǔ","zhōng","yú","zhǎo","dào","chē","zhàn","le"]','wo3 zhao3 le0 hen3 jiu3 zhong1 yu2 zhao3 dao4 che1 zhan4 le0','id','Saya sudah mencari lama dan akhirnya menemukan stasiun.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-jixu','word-jixu',NULL,'休息一下，我们再继续学习。','["xiū","xi","yí","xià","wǒ","men","zài","jì","xù","xué","xí"]','xiu1 xi0 yi2 xia4 wo3 men0 zai4 ji4 xu4 xue2 xi2','id','Beristirahat sebentar, lalu kita lanjut belajar.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-gan-kuai','word-gan-kuai',NULL,'快要下雨了，我们赶快回家吧。','["kuài","yào","xià","yǔ","le","wǒ","men","gǎn","kuài","huí","jiā","ba"]','kuai4 yao4 xia4 yu3 le0 wo3 men0 gan3 kuai4 hui2 jia1 ba0','id','Sebentar lagi hujan; ayo cepat pulang.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-jihua','word-jihua',NULL,'周末你有什么计划？','["zhōu","mò","nǐ","yǒu","shén","me","jì","huà"]','zhou1 mo4 ni3 you3 shen2 me0 ji4 hua4','id','Apa rencanamu pada akhir pekan?','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-canjia','word-canjia',NULL,'她周末参加中文活动。','["tā","zhōu","mò","cān","jiā","zhōng","wén","huó","dòng"]','ta1 zhou1 mo4 can1 jia1 zhong1 wen2 huo2 dong4','id','Dia ikut kegiatan Mandarin pada akhir pekan.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-huodong','word-huodong',NULL,'学校今天有一个文化活动。','["xué","xiào","jīn","tiān","yǒu","yí","ge","wén","huà","huó","dòng"]','xue2 xiao4 jin1 tian1 you3 yi2 ge0 wen2 hua4 huo2 dong4','id','Hari ini ada kegiatan budaya di sekolah.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-jianmian','word-jianmian',NULL,'我们明天下午在咖啡店见面。','["wǒ","men","míng","tiān","xià","wǔ","zài","kā","fēi","diàn","jiàn","miàn"]','wo3 men0 ming2 tian1 xia4 wu3 zai4 ka1 fei1 dian4 jian4 mian4','id','Kita bertemu besok sore di kedai kopi.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-haimei','word-haimei',NULL,'电影还没开始，我们先买水吧。','["diàn","yǐng","hái","méi","kāi","shǐ","wǒ","men","xiān","mǎi","shuǐ","ba"]','dian4 ying3 hai2 mei2 kai1 shi3 wo3 men0 xian1 mai3 shui3 ba0','id','Filmnya belum mulai; kita beli air dulu.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-renwei','word-renwei',NULL,'我认为每天听中文很有用。','["wǒ","rèn","wéi","měi","tiān","tīng","zhōng","wén","hěn","yǒu","yòng"]','wo3 ren4 wei2 mei3 tian1 ting1 zhong1 wen2 hen3 you3 yong4','id','Menurut saya, mendengarkan bahasa Mandarin setiap hari sangat bermanfaat.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-bijiao','word-bijiao',NULL,'这家店比较安静，适合学习。','["zhè","jiā","diàn","bǐ","jiào","ān","jìng","shì","hé","xué","xí"]','zhe4 jia1 dian4 bi3 jiao4 an1 jing4 shi4 he2 xue2 xi2','id','Kedai ini cukup tenang dan cocok untuk belajar.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-renzhen','word-renzhen',NULL,'她认真地练习每一个汉字。','["tā","rèn","zhēn","de","liàn","xí","měi","yí","ge","hàn","zì"]','ta1 ren4 zhen1 de0 lian4 xi2 mei3 yi2 ge0 han4 zi4','id','Dia berlatih setiap hanzi dengan sungguh-sungguh.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-tebie','word-tebie',NULL,'今天的中文课特别有意思。','["jīn","tiān","de","zhōng","wén","kè","tè","bié","yǒu","yì","si"]','jin1 tian1 de0 zhong1 wen2 ke4 te4 bie2 you3 yi4 si0','id','Pelajaran Mandarin hari ini sangat menarik.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-kaishi','word-kaishi',NULL,'我们八点开始上课。','["wǒ","men","bā","diǎn","kāi","shǐ","shàng","kè"]','wo3 men0 ba1 dian3 kai1 shi3 shang4 ke4','id','Kita mulai kelas pukul delapan.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-wancheng','word-wancheng',NULL,'我已经完成今天的作业了。','["wǒ","yǐ","jīng","wán","chéng","jīn","tiān","de","zuò","yè","le"]','wo3 yi3 jing1 wan2 cheng2 jin1 tian1 de0 zuo4 ye4 le0','id','Saya sudah menyelesaikan pekerjaan rumah hari ini.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-jieguo','word-jieguo',NULL,'练习以后，结果比我想的好。','["liàn","xí","yǐ","hòu","jié","guǒ","bǐ","wǒ","xiǎng","de","hǎo"]','lian4 xi2 yi3 hou4 jie2 guo3 bi3 wo3 xiang3 de0 hao3','id','Setelah berlatih, hasilnya lebih baik daripada yang saya kira.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-jihui','word-jihui',NULL,'有机会的话，我想去中国旅行。','["yǒu","jī","huì","de","huà","wǒ","xiǎng","qù","zhōng","guó","lǚ","xíng"]','you3 ji1 hui4 de0 hua4 wo3 xiang3 qu4 zhong1 guo2 lv3 xing2','id','Kalau ada kesempatan, saya ingin bepergian ke Tiongkok.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-jingyan','word-jingyan',NULL,'多和中国朋友聊天，可以积累经验。','["duō","hé","zhōng","guó","péng","you","liáo","tiān","kě","yǐ","jī","lěi","jīng","yàn"]','duo1 he2 zhong1 guo2 peng2 you0 liao2 tian1 ke3 yi3 ji1 lei3 jing1 yan4','id','Banyak berbincang dengan teman Tiongkok dapat menambah pengalaman.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-wenhua','word-wenhua',NULL,'学语言的时候，也可以了解当地文化。','["xué","yǔ","yán","de","shí","hou","yě","kě","yǐ","liǎo","jiě","dāng","dì","wén","huà"]','xue2 yu3 yan2 de0 shi2 hou0 ye3 ke3 yi3 liao3 jie3 dang1 di4 wen2 hua4','id','Saat belajar bahasa, kita juga bisa mengenal budaya setempat.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-xiguan','word-xiguan',NULL,'我习惯早上听中文新闻。','["wǒ","xí","guàn","zǎo","shang","tīng","zhōng","wén","xīn","wén"]','wo3 xi2 guan4 zao3 shang0 ting1 zhong1 wen2 xin1 wen2','id','Saya terbiasa mendengarkan berita Mandarin pada pagi hari.','source-course-expansion-2026-09-advanced','approved'),
  ('example-word-bianhua','word-bianhua',NULL,'天气变化很快，出门要带伞。','["tiān","qì","biàn","huà","hěn","kuài","chū","mén","yào","dài","sǎn"]','tian1 qi4 bian4 hua4 hen3 kuai4 chu1 men2 yao4 dai4 san3','id','Cuaca berubah cepat; bawalah payung saat keluar.','source-course-expansion-2026-09-advanced','approved');

